import { useEffect, useState } from "react";
import api from "../api";
import socket from "../socket";
import { useToast } from "../context/ToastContext";
import Skeleton from "../components/Skeleton";
import "../components/skeleton.css";

export default function ProviderDashboard() {

  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);

  const { addToast } = useToast();

  // -----------------------------
  // GET TOKEN + PROVIDER INFO
  // -----------------------------

  const token = localStorage.getItem("token");

  let providerId = "";

  if (token) {

    try {

      const decoded = JSON.parse(
        atob(token.split(".")[1])
      );

      providerId = decoded.id;

    } catch (err) {
      console.log(err);
    }

  }

  // -----------------------------
  // FETCH BOOKINGS
  // -----------------------------

  const fetchBookings = async () => {

    try {

      setLoading(true);

      const res = await api.get(
        "/bookings/provider-bookings"
      );

      setBookings(res.data || []);

    } catch (err) {

      console.log(err);

      addToast(
        "Unable to load bookings",
        "error"
      );

    } finally {

      setLoading(false);

    }

  };

  // -----------------------------
  // SOCKET CONNECTION
  // -----------------------------

  useEffect(() => {

    if (token) {

      socket.emit("register", {
        token
      });

    }

    fetchBookings();

    socket.on(
      "booking-created",
      (data) => {

        console.log(
          "NEW BOOKING:",
          data
        );

        addToast(
          `New booking for ${data.booking.serviceName}`,
          "success"
        );

        fetchBookings();

      }
    );

    socket.on(
      "booking-update",
      () => {

        fetchBookings();

      }
    );

    return () => {

      socket.off("booking-created");

      socket.off("booking-update");

    };

  }, []);

  // -----------------------------
  // LIVE LOCATION
  // -----------------------------

  useEffect(() => {

    if (
      !providerId ||
      !navigator.geolocation
    ) return;

    const watchId =
      navigator.geolocation.watchPosition(

        (position) => {

          socket.emit(
            "provider-location",
            {

              providerId,

              lat:
                position.coords.latitude,

              lng:
                position.coords.longitude

            }
          );

        },

        (err) => {

          console.log(
            "Location error",
            err
          );

        },

        {
          enableHighAccuracy: true
        }

      );

    return () => {

      navigator.geolocation.clearWatch(
        watchId
      );

    };

  }, [providerId]);

  // -----------------------------
  // PROVIDER ACTION
  // -----------------------------

  const providerAction = async (
    bookingId,
    action
  ) => {

    try {

      await api.put(

        `/bookings/provider-action/${bookingId}`,

        { action }

      );

      addToast(

        `Booking ${action}ed successfully`,

        "success"

      );

      fetchBookings();

    } catch (err) {

      console.log(err);

      addToast(
        "Action failed",
        "error"
      );

    }

  };

  // -----------------------------
  // FILTER BOOKINGS
  // -----------------------------

  const activeBookings =
    bookings.filter(

      (booking) =>

        booking.status !== "completed" &&
        booking.status !== "cancelled"

    );

  // -----------------------------
  // UI
  // -----------------------------

  return (

    <div className="dashboard-container">

      <header className="dashboard-header">

        <div className="dashboard-logo">

          🚀 FastAid

        </div>

        <button
          className="logout-btn"
          onClick={() => {

            localStorage.removeItem(
              "token"
            );

            window.location.href = "/";

          }}
        >
          Logout
        </button>

      </header>

      <div className="dashboard-content">

        <h1 className="dashboard-title">

          Provider Dashboard 🛠️

        </h1>

        <p className="dashboard-subtitle">

          Manage your service requests

        </p>

        {loading ? (

          <div style={{ marginTop: 20 }}>

            <Skeleton
              count={4}
              height="100px"
            />

          </div>

        ) : activeBookings.length === 0 ? (

          <div className="no-requests">

            <div className="no-requests-icon">
              🔔
            </div>

            <div className="no-requests-text">

              No active bookings

            </div>

          </div>

        ) : (

          <div className="booking-list">

            {activeBookings.map(
              (booking) => (

                <div
                  key={booking._id}
                  className="booking-card"
                >

                  <h3>

                    {
                      booking.serviceName
                    }

                  </h3>

                  <p>

                    👤 Customer:
                    {" "}
                    {
                      booking.userId?.name
                    }

                  </p>

                  <p>

                    📍 Location:
                    {" "}
                    {
                      booking.location ||
                      booking.locationDetails?.fullAddress
                    }

                  </p>

                  <p>

                    💰 Amount:
                    ₹
                    {
                      booking.servicePrice
                    }

                  </p>

                  <p>

                    📌 Status:
                    {" "}
                    {
                      booking.status
                    }

                  </p>

                  {(booking.status ===
                    "assigned" ||

                    booking.status ===
                    "pending") && (

                    <div
                      className="provider-buttons"
                    >

                      <button

                        className="provider-btn provider-btn-accept"

                        onClick={() =>

                          providerAction(
                            booking._id,
                            "accept"
                          )

                        }

                      >

                        ✅ Accept

                      </button>

                      <button

                        className="provider-btn provider-btn-reject"

                        onClick={() =>

                          providerAction(
                            booking._id,
                            "reject"
                          )

                        }

                      >

                        ❌ Reject

                      </button>

                    </div>

                  )}

                </div>

              )
            )}

          </div>

        )}

      </div>

    </div>

  );

}
